@dataclass(frozen=True)
class Experiment:
    label: str
    args: list[str]
    notes: str

    @property
    def session(self) -> str:
        return f"track-c-{self.label}"

    @property
    def log_path(self) -> Path:
        return LOG_DIR / f"{self.label}.log"


def independent_region_experiment(
    label: str,
    *,
    strength: float,
    pan: float,
    seed: int = 0,
    freq_bands: int = 10,
    grad_clip: float = 0.5,
    min_ocr: float = 0.50,
    min_motion: float = 0.04,
) -> Experiment:
    seed_note = f", seed {seed}" if seed else ""
    return Experiment(
        label=label,
        notes=(
            "C44 independent-region stress: coarse page regions move/scale at separate speeds "
            f"with strength {strength:g}, pan {pan:g}, freq{freq_bands}, grad clip {grad_clip:g}{seed_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution="1536x864",
            steps=5500,
            seed=seed,
            freq_bands=freq_bands,
            grad_clip=grad_clip,
            edge_ratio=0.09,
            edge_weight=0.9,
            motion_mode="static",
            motion_strength=0.0,
            video_layout_mode="independent-regions",
            layout_transform_strength=strength,
            layout_transform_pan=pan,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


def independent_field_experiment(
    label: str,
    *,
    strength: float,
    pan: float,
    seed: int = 0,
    freq_bands: int = 10,
    grad_clip: float = 0.5,
    min_ocr: float = 0.50,
    min_motion: float = 0.03,
) -> Experiment:
    seed_note = f", seed {seed}" if seed else ""
    return Experiment(
        label=label,
        notes=(
            "C45 smooth independent-field stress: no hard region blanking; separate local affine fields "
            f"blend continuously with strength {strength:g}, pan {pan:g}, freq{freq_bands}, grad clip {grad_clip:g}{seed_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution="1536x864",
            steps=5500,
            seed=seed,
            freq_bands=freq_bands,
            grad_clip=grad_clip,
            edge_ratio=0.09,
            edge_weight=0.9,
            motion_mode="static",
            motion_strength=0.0,
            video_layout_mode="independent-field",
            layout_transform_strength=strength,
            layout_transform_pan=pan,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


