def learned_independent_field_experiment(
    label: str,
    *,
    motion_strength: float,
    steps: int = 5500,
    seed: int = 0,
    freq_bands: int = 10,
    grad_clip: float | None = None,
    min_ocr: float = 0.35,
    min_motion: float = 0.025,
) -> Experiment:
    clip_note = f", grad clip {grad_clip:g}" if grad_clip is not None else ""
    seed_note = f", seed {seed}" if seed else ""
    return Experiment(
        label=label,
        notes=(
            "C45 learned independent-field stress: train the renderer to generate multi-region motion "
            f"directly from x,y,t with motion {motion_strength:g}, freq{freq_bands}{clip_note}{seed_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution="1536x864",
            steps=steps,
            seed=seed,
            freq_bands=freq_bands,
            grad_clip=grad_clip,
            flow=motion_strength,
            edge_ratio=0.09,
            edge_weight=0.9,
            motion_mode="independent-field",
            motion_strength=motion_strength,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


def learned_independent_translation_experiment(
    label: str,
    *,
    motion_strength: float,
    steps: int = 7000,
    seed: int = 0,
    channels: int | None = None,
    hidden: int | None = None,
    freq_bands: int = 10,
    lr: float | None = None,
    lr_schedule: str | None = None,
    min_lr_ratio: float | None = None,
    grad_clip: float | None = 0.5,
    l1_loss_weight: float | None = None,
    gradient_loss_weight: float | None = None,
    gradient_loss_ratio: float | None = None,
    gradient_loss_offset_px: float | None = None,
    source_remnant_loss_weight: float | None = None,
    source_remnant_margin: float | None = None,
    source_remnant_change_floor: float | None = None,
    source_remnant_reference: str | None = None,
    source_remnant_time_power: float | None = None,
    source_remnant_sample_ratio: float | None = None,
    source_remnant_sample_time_width: float | None = None,
    source_remnant_direct_loss_weight: float | None = None,
    source_remnant_direct_region: str | None = None,
    edge_ratio: float = 0.09,
    edge_weight: float = 0.9,
    text_box_sample_ratio: float = 0.0,
    text_box_loss_weight: float = 0.0,
    text_box_padding: int = 0,
    min_ocr: float = 0.35,
    min_motion: float = 0.025,
) -> Experiment:
    clip_note = f", grad clip {grad_clip:g}" if grad_clip is not None else ""
    l1_note = f", L1 {l1_loss_weight:g}" if l1_loss_weight else ""
    grad_note = (
        f", gradient {gradient_loss_weight:g}@{gradient_loss_ratio:g}"
        if gradient_loss_weight and gradient_loss_ratio
        else ""
    )
    remnant_note = (
        f", source-remnant contrast {source_remnant_loss_weight:g}"
        if source_remnant_loss_weight
        else ""
    )
    if remnant_note and source_remnant_reference:
        remnant_note += f" ref {source_remnant_reference}"
    if remnant_note and source_remnant_time_power is not None:
        remnant_note += f" timepow {source_remnant_time_power:g}"
    if remnant_note and source_remnant_sample_ratio:
        remnant_note += f" srcsample {source_remnant_sample_ratio:g}"
    direct_remnant_note = (
        f", source-remnant direct {source_remnant_direct_loss_weight:g}"
        if source_remnant_direct_loss_weight
        else ""
    )
    if direct_remnant_note and source_remnant_direct_region:
        direct_remnant_note += f" region {source_remnant_direct_region}"
    seed_note = f", seed {seed}" if seed else ""
    return Experiment(
        label=label,
        notes=(
            "C46 learned independent-translation stress: train the renderer to generate local translations "
            f"directly from x,y,t with scale disabled, motion {motion_strength:g}, {steps} steps, freq{freq_bands}{clip_note}{l1_note}{grad_note}{remnant_note}{direct_remnant_note}{seed_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution="1536x864",
            steps=steps,
            seed=seed,
            channels=channels,
            hidden=hidden,
            freq_bands=freq_bands,
            lr=lr,
            lr_schedule=lr_schedule,
            min_lr_ratio=min_lr_ratio,
            grad_clip=grad_clip,
            l1_loss_weight=l1_loss_weight,
            gradient_loss_weight=gradient_loss_weight,
            gradient_loss_ratio=gradient_loss_ratio,
            gradient_loss_offset_px=gradient_loss_offset_px,
            source_remnant_loss_weight=source_remnant_loss_weight,
            source_remnant_margin=source_remnant_margin,
            source_remnant_change_floor=source_remnant_change_floor,
            source_remnant_reference=source_remnant_reference,
            source_remnant_time_power=source_remnant_time_power,
            source_remnant_sample_ratio=source_remnant_sample_ratio,
            source_remnant_sample_time_width=source_remnant_sample_time_width,
            source_remnant_direct_loss_weight=source_remnant_direct_loss_weight,
            source_remnant_direct_region=source_remnant_direct_region,
            flow=motion_strength,
            edge_ratio=edge_ratio,
            edge_weight=edge_weight,
            text_box_sample_ratio=text_box_sample_ratio,
            text_box_loss_weight=text_box_loss_weight,
            text_box_padding=text_box_padding,
            motion_mode="independent-translate",
            motion_strength=motion_strength,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


def learned_sprite_translation_experiment(
    label: str,
    *,
    motion_strength: float,
    steps: int = 7000,
    seed: int = 0,
    channels: int | None = None,
    hidden: int | None = None,
    freq_bands: int = 10,
    lr: float | None = None,
    lr_schedule: str | None = None,
    min_lr_ratio: float | None = None,
    grad_clip: float | None = 0.5,
    l1_loss_weight: float | None = None,
    edge_ratio: float = 0.09,
    edge_weight: float = 0.9,
    text_box_sample_ratio: float = 0.0,
    text_box_loss_weight: float = 0.0,
    text_box_padding: int = 0,
    min_ocr: float = 0.35,
    min_motion: float = 0.025,
) -> Experiment:
    clip_note = f", grad clip {grad_clip:g}" if grad_clip is not None else ""
    l1_note = f", L1 {l1_loss_weight:g}" if l1_loss_weight else ""
    seed_note = f", seed {seed}" if seed else ""
    text_note = ", text-weighted" if text_box_loss_weight > 0 or text_box_sample_ratio > 0 else ""
    return Experiment(
        label=label,
        notes=(
            "C47 learned sprite-translation stress: region content translates as a region in the training target, "
            f"but output is still direct neural-canvas pixels; motion {motion_strength:g}, {steps} steps, "
            f"freq{freq_bands}{clip_note}{seed_note}{text_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution="1536x864",
            steps=steps,
            seed=seed,
            channels=channels,
            hidden=hidden,
            freq_bands=freq_bands,
            lr=lr,
            lr_schedule=lr_schedule,
            min_lr_ratio=min_lr_ratio,
            grad_clip=grad_clip,
            flow=motion_strength,
            edge_ratio=edge_ratio,
            edge_weight=edge_weight,
            text_box_sample_ratio=text_box_sample_ratio,
            text_box_loss_weight=text_box_loss_weight,
            text_box_padding=text_box_padding,
            motion_mode="independent-sprite-translate",
            motion_strength=motion_strength,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


def learned_layout_reflow_experiment(
    label: str,
    *,
    amount: float = 1.0,
    flow_scale: float = 0.08,
    steps: int = 9000,
    train_resolution: str = "1536x864",
    batch_size: int | None = None,
    seed: int = 0,
    channels: int | None = None,
    hidden: int | None = None,
    detail_channels: int | None = None,
    detail_hidden: int | None = None,
    detail_scale: float | None = None,
    detail_init_scale: float | None = None,
    source_coord_features: int | None = None,
    source_coord_mid_scale: float | None = None,
    latent_neighborhood_mode: str | None = None,
    latent_neighborhood_radius_px: float | None = None,
    latent_sample_mode: str | None = None,
    context_channels: int | None = None,
    context_scale: float | None = None,
    context_init_scale: float | None = None,
    context_sample_mode: str | None = None,
    decoder_mode: str | None = None,
    target_branch_scale: float | None = None,
    target_branch_hidden: int | None = None,
    target_canvas_mode: str | None = None,
    target_canvas_init_scale: float | None = None,
    rgb_skip_scale: float | None = None,
    rgb_skip_mode: str | None = None,
    rgb_skip_base_scale: float | None = None,
    rgb_skip_gate_mode: str | None = None,
    rgb_skip_gate_init: float | None = None,
    freq_bands: int = 10,
    time_bands: int | None = None,
    lr: float | None = None,
    lr_schedule: str | None = None,
    min_lr_ratio: float | None = None,
    grad_clip: float | None = 0.5,
    l1_loss_weight: float | None = None,
    gradient_loss_weight: float | None = None,
    gradient_loss_ratio: float | None = None,
    gradient_loss_offset_px: float | None = None,
    source_remnant_loss_weight: float | None = None,
    source_remnant_margin: float | None = None,
    source_remnant_change_floor: float | None = None,
    source_remnant_reference: str | None = None,
    source_remnant_time_power: float | None = None,
    source_remnant_sample_ratio: float | None = None,
    source_remnant_sample_time_width: float | None = None,
    source_remnant_direct_loss_weight: float | None = None,
    source_remnant_direct_region: str | None = None,
    edge_ratio: float = 0.09,
    edge_weight: float = 0.9,
    text_box_sample_ratio: float = 0.0,
    text_box_loss_weight: float = 0.0,
    text_box_padding: int = 0,
    layout_target_sampling: int | None = None,
    layout_target_weighting: int | None = None,
    layout_target_sampling_ratio: float | None = None,
    layout_target_mid_sampling_ratio: float | None = None,
    layout_target_mid_time_width: float | None = None,
    layout_target_pair_ratio: float | None = None,
    layout_target_pair_weight: float | None = None,
    layout_mid_time_ratio: float | None = None,
    layout_mid_time_width: float | None = None,
    layout_flow_loss_weight: float | None = None,
    layout_oracle_flow: int | None = None,
    layout_motion_curriculum_ratio: float | None = None,
    layout_motion_curriculum_start: float | None = None,
    layout_endpoint_ratio: float | None = None,
    layout_endpoint_target_ratio: float | None = None,
    motion_mode: str = "layout-reflow",
    clean_target_variant: str | None = None,
    min_ocr: float = 0.35,
    min_motion: float = 0.035,
) -> Experiment:
    clean_mode = motion_mode in {
        "layout-clean-reflow",
        "clean-layout-reflow",
        "layout-clean-move-reveal",
        "clean-layout-move-reveal",
        "clean-move-reveal",
        "layout-clean-independent-recompose",
        "clean-layout-independent-recompose",
        "clean-independent-recompose",
    }
    proof_name = "Learned clean page-state proof" if clean_mode else "Learned layout-reflow proof"
    if motion_mode in {"layout-clean-independent-recompose", "clean-layout-independent-recompose", "clean-independent-recompose"}:
        proof_detail = (
            "the training target independently recomposes source and target page regions before resolving "
            "to a separate clean page state at the midpoint"
        )
    elif motion_mode in {"layout-clean-move-reveal", "clean-layout-move-reveal", "clean-move-reveal"}:
        proof_detail = (
            "the training target moves the source layer while the separate clean target page eases into place"
        )
    elif clean_mode:
        proof_detail = "the training target is a separate clean page state at the midpoint, then loops back to the source"
    else:
        proof_detail = "the training target moves text/content blocks and resizes/repositions the illustration into a new page layout"
    clip_note = f", grad clip {grad_clip:g}" if grad_clip is not None else ""
    l1_note = f", L1 {l1_loss_weight:g}" if l1_loss_weight else ""
    grad_note = (
        f", gradient {gradient_loss_weight:g}@{gradient_loss_ratio:g}"
        if gradient_loss_weight and gradient_loss_ratio
        else ""
    )
    remnant_note = (
        f", source-remnant contrast {source_remnant_loss_weight:g}"
        if source_remnant_loss_weight
        else ""
    )
    if remnant_note and source_remnant_reference:
        remnant_note += f" ref {source_remnant_reference}"
    if remnant_note and source_remnant_time_power is not None:
        remnant_note += f" timepow {source_remnant_time_power:g}"
    if remnant_note and source_remnant_sample_ratio:
        remnant_note += f" srcsample {source_remnant_sample_ratio:g}"
    direct_remnant_note = (
        f", source-remnant direct {source_remnant_direct_loss_weight:g}"
        if source_remnant_direct_loss_weight
        else ""
    )
    if direct_remnant_note and source_remnant_direct_region:
        direct_remnant_note += f" region {source_remnant_direct_region}"
    seed_note = f", seed {seed}" if seed else ""
    detail_note = (
        f", residual detail c{detail_channels}/h{detail_hidden or hidden or 'base'} scale {detail_scale:g}"
        if detail_channels and detail_scale
        else ""
    )
    source_coord_note = ", source-coord features" if source_coord_features else ""
    if source_coord_features and source_coord_mid_scale is not None and source_coord_mid_scale < 1.0:
        source_coord_note += f" midscale {source_coord_mid_scale:g}"
    neighborhood_note = (
        f", latent {latent_neighborhood_mode} neighborhood r{latent_neighborhood_radius_px:g}px {latent_sample_mode or 'source'}"
        if latent_neighborhood_mode and latent_neighborhood_radius_px
        else ""
    )
    context_note = (
        f", context c{context_channels} scale {context_scale if context_scale is not None else 0.25:g}"
        f" {context_sample_mode or 'source'}"
        if context_channels
        else ""
    )
    decoder_note = (
        f", decoder {decoder_mode} target-scale {target_branch_scale if target_branch_scale is not None else 0:g}"
        f" target-h{target_branch_hidden if target_branch_hidden is not None else 'base'}"
        if decoder_mode
        else ""
    )
    target_canvas_note = (
        f", target-state canvas {target_canvas_mode} init {target_canvas_init_scale if target_canvas_init_scale is not None else 0.02:g}"
        if target_canvas_mode
        else ""
    )
    rgb_skip_note = (
        f", rgb neural texture skip base {rgb_skip_base_scale if rgb_skip_base_scale is not None else 1:g}"
        f" residual {rgb_skip_scale:g} {rgb_skip_mode or 'source'}"
        f"{' gate ' + rgb_skip_gate_mode if rgb_skip_gate_mode else ''}"
        if rgb_skip_scale
        else ""
    )
    text_note = ", text-weighted" if text_box_loss_weight > 0 or text_box_sample_ratio > 0 else ""
    target_note = ", target-side reflow sampling" if layout_target_sampling or layout_target_weighting else ""
    if layout_target_sampling and layout_target_sampling_ratio is not None and layout_target_sampling_ratio < 1.0:
        target_note += f" ratio {layout_target_sampling_ratio:g}"
    if layout_target_mid_sampling_ratio:
        target_note += f", direct target-mid sampling ratio {layout_target_mid_sampling_ratio:g}"
        if layout_target_mid_time_width is not None:
            target_note += f" width {layout_target_mid_time_width:g}"
    if layout_target_pair_ratio:
        target_note += f", paired target loss ratio {layout_target_pair_ratio:g}"
        if layout_target_pair_weight is not None:
            target_note += f" weight {layout_target_pair_weight:g}"
    mid_note = f", mid-time {layout_mid_time_ratio:g}" if layout_mid_time_ratio else ""
    flow_loss_note = f", flow supervision {layout_flow_loss_weight:g}" if layout_flow_loss_weight else ""
    oracle_note = ", oracle layout flow" if layout_oracle_flow else ""
    curriculum_note = (
        f", motion curriculum {layout_motion_curriculum_ratio:g}/{layout_motion_curriculum_start or 0:g}"
        if layout_motion_curriculum_ratio
        else ""
    )
    endpoint_note = (
        f", endpoint anchors {layout_endpoint_ratio:g}/{layout_endpoint_target_ratio if layout_endpoint_target_ratio is not None else 0.5:g}"
        if layout_endpoint_ratio
        else ""
    )
    clean_variant_note = f", clean target {clean_target_variant}" if clean_mode and clean_target_variant else ""
    return Experiment(
        label=label,
        notes=(
            f"{proof_name}: {proof_detail}; output remains direct neural-canvas pixels. "
            f"amount {amount:g}, flow scale {flow_scale:g}, {steps} steps, freq{freq_bands}{clip_note}{l1_note}{grad_note}{remnant_note}{direct_remnant_note}{seed_note}{detail_note}{source_coord_note}{neighborhood_note}{context_note}{decoder_note}{target_canvas_note}{rgb_skip_note}{text_note}{target_note}{mid_note}{flow_loss_note}{oracle_note}{curriculum_note}{endpoint_note}{clean_variant_note}."
        ),
        args=general_visual_motion_args(
            label,
            train_resolution=train_resolution,
            steps=steps,
            batch_size=batch_size,
            seed=seed,
            channels=channels,
            hidden=hidden,
            detail_channels=detail_channels,
            detail_hidden=detail_hidden,
            detail_scale=detail_scale,
            detail_init_scale=detail_init_scale,
            source_coord_features=source_coord_features,
            source_coord_mid_scale=source_coord_mid_scale,
            latent_neighborhood_mode=latent_neighborhood_mode,
            latent_neighborhood_radius_px=latent_neighborhood_radius_px,
            latent_sample_mode=latent_sample_mode,
            context_channels=context_channels,
            context_scale=context_scale,
            context_init_scale=context_init_scale,
            context_sample_mode=context_sample_mode,
            decoder_mode=decoder_mode,
            target_branch_scale=target_branch_scale,
            target_branch_hidden=target_branch_hidden,
            target_canvas_mode=target_canvas_mode,
            target_canvas_init_scale=target_canvas_init_scale,
            rgb_skip_scale=rgb_skip_scale,
            rgb_skip_mode=rgb_skip_mode,
            rgb_skip_base_scale=rgb_skip_base_scale,
            rgb_skip_gate_mode=rgb_skip_gate_mode,
            rgb_skip_gate_init=rgb_skip_gate_init,
            freq_bands=freq_bands,
            time_bands=time_bands,
            lr=lr,
            lr_schedule=lr_schedule,
            min_lr_ratio=min_lr_ratio,
            grad_clip=grad_clip,
            l1_loss_weight=l1_loss_weight,
            gradient_loss_weight=gradient_loss_weight,
            gradient_loss_ratio=gradient_loss_ratio,
            gradient_loss_offset_px=gradient_loss_offset_px,
            source_remnant_loss_weight=source_remnant_loss_weight,
            source_remnant_margin=source_remnant_margin,
            source_remnant_change_floor=source_remnant_change_floor,
            source_remnant_reference=source_remnant_reference,
            source_remnant_time_power=source_remnant_time_power,
            source_remnant_sample_ratio=source_remnant_sample_ratio,
            source_remnant_sample_time_width=source_remnant_sample_time_width,
            source_remnant_direct_loss_weight=source_remnant_direct_loss_weight,
            source_remnant_direct_region=source_remnant_direct_region,
            flow=flow_scale,
            edge_ratio=edge_ratio,
            edge_weight=edge_weight,
            text_box_sample_ratio=text_box_sample_ratio,
            text_box_loss_weight=text_box_loss_weight,
            text_box_padding=text_box_padding,
            layout_target_sampling=layout_target_sampling,
            layout_target_weighting=layout_target_weighting,
            layout_target_sampling_ratio=layout_target_sampling_ratio,
            layout_target_mid_sampling_ratio=layout_target_mid_sampling_ratio,
            layout_target_mid_time_width=layout_target_mid_time_width,
            layout_target_pair_ratio=layout_target_pair_ratio,
            layout_target_pair_weight=layout_target_pair_weight,
            layout_mid_time_ratio=layout_mid_time_ratio,
            layout_mid_time_width=layout_mid_time_width,
            layout_flow_loss_weight=layout_flow_loss_weight,
            layout_oracle_flow=layout_oracle_flow,
            layout_motion_curriculum_ratio=layout_motion_curriculum_ratio,
            layout_motion_curriculum_start=layout_motion_curriculum_start,
            layout_endpoint_ratio=layout_endpoint_ratio,
            layout_endpoint_target_ratio=layout_endpoint_target_ratio,
            motion_mode=motion_mode,
            clean_target_variant=clean_target_variant,
            motion_strength=amount,
            min_ocr=min_ocr,
            min_motion=min_motion,
        ),
    )


